function usedFontFamilies(root: HTMLElement): Set<string> {
  const families = new Set<string>();
  const add = (value: string) => {
    for (const part of value.split(',')) {
      families.add(part.trim().replace(/^["']|["']$/g, '').toLowerCase());
    }
  };
  add(getComputedStyle(root).fontFamily);
  root.querySelectorAll('*').forEach((el) => {
    add(getComputedStyle(el).fontFamily);
  });
  return families;
}

function isFontFaceRule(rule: CSSRule): rule is CSSFontFaceRule {
  return rule.type === 5; /* CSSRule.FONT_FACE_RULE */
}

function fontFaceFamily(rule: CSSFontFaceRule): string {
  return rule.style
    .getPropertyValue('font-family')
    .replace(/^["']|["']$/g, '')
    .trim()
    .toLowerCase();
}

async function blobToDataUrl(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

async function inlineFontFaceUrls(rule: CSSFontFaceRule): Promise<string> {
  const base = rule.parentStyleSheet?.href ?? document.baseURI;
  let cssText = rule.cssText;
  for (const match of cssText.matchAll(/url\((['"]?)([^'")]+)\1\)/g)) {
    const rawUrl = match[2];
    if (rawUrl.startsWith('data:')) continue;
    try {
      const response = await fetch(new URL(rawUrl, base).href);
      const dataUrl = await blobToDataUrl(await response.blob());
      cssText = cssText.replace(match[0], `url(${dataUrl})`);
    } catch {
      /* font file not fetchable, leave the original url */
    }
  }
  return cssText;
}

/**
 * Build @font-face CSS with font files inlined as data URLs, for the fonts
 * actually used inside `root`, taken only from same-origin stylesheets.
 *
 * DOM-to-image capture rasterizes an SVG that cannot fetch external resources,
 * so fonts referenced by url() do not render unless embedded as data URLs. This
 * is fed to html-to-image as fontEmbedCSS with skipFonts:true so it never reads
 * cross-origin stylesheets itself (which throw on .cssRules).
 */
export async function buildInlinedFontFaceCss(
  root: HTMLElement,
): Promise<string> {
  const wanted = usedFontFamilies(root);
  const rules: CSSFontFaceRule[] = [];
  for (const sheet of Array.from(document.styleSheets)) {
    let cssRules: CSSRuleList;
    try {
      cssRules = sheet.cssRules;
    } catch {
      continue; /* cross-origin stylesheet, not readable */
    }
    for (const rule of Array.from(cssRules)) {
      if (isFontFaceRule(rule) && wanted.has(fontFaceFamily(rule))) {
        rules.push(rule);
      }
    }
  }
  const inlined = await Promise.all(rules.map(inlineFontFaceUrls));
  return inlined.join('\n');
}
