<template>
  <q-card
    flat
    class="page-background container-height full-width"
  >
    <q-card-section class="row justify-center q-pl-md q-pr-md q-pt-md">
      <span class="secondary-c-text text-h6 text-weight-bold">
        {{ $t('support_ticket') }}
      </span>
    </q-card-section>

    <q-separator />

    <q-card-section class="q-pa-md">
      <div class="q-mt-md">
        <!-- Name input -->
        <q-input
          dense
          outlined
          v-model="supportTicket.fullname"
          class="back-white"
          :label="$t('name')"
        />
      </div>

      <div class="q-mt-md">
        <!-- Email input -->
        <q-input
          dense
          outlined
          v-model="supportTicket.email"
          class="back-white"
          :label="$t('email')"
        />
      </div>

      <div class="q-mt-md">
        <!-- Subject input -->
        <q-input
          dense
          outlined
          v-model="supportTicket.subject"
          class="back-white"
          :label="$t('subject')"
        />
      </div>

      <div class="q-mt-md">
        <q-select
          dense
          outlined
          :options="priorityOptions"
          class="back-white"
          v-model="supportTicket.priority"
          :label="$t('priority')"
        />
      </div>

      <div class="q-mt-md">
        <!-- message input -->
        <q-input
          dense
          outlined
          v-model="supportTicket.message"
          class="back-white"
          :label="$t('message')"
          type="textarea"
        />
      </div>

      <div class="q-mt-md">
        <div id="screen-button" class="text-center">
          <f-btn
            :loading="loading"
            class="full-width"
            appearance="secondary"
            :label="$t('screenshot')"
            @click="takeScreenshot()"
          >
            <template v-slot:loading>
              <q-spinner-hourglass class="on-left" />
            </template>
          </f-btn>
        </div>
        <div id="display"></div>
        <!-- message input -->
      </div>

      <div class="q-mt-md">
        <q-file
          outlined
          class="back-white"
          :label="$t('upload_file')"
          v-model="supportTicket.file"
        >
          <template v-slot:prepend>
            <q-icon name="attach_file" />
          </template>
        </q-file>
      </div>
    </q-card-section>

    <q-card-actions align="center" class="q-pb-md">
      <f-btn
        color="primary"
        unelevated
        :label="$t('send')"
        @click="sendSupportTicket"
      />
    </q-card-actions>
  </q-card>
</template>

<script lang="ts">
import { supportApiService } from 'src/services';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { defineComponent, ref } from 'vue';
import { i18n } from 'src/boot/i18n';
import { LocalStorage } from 'quasar';
import type { dynamicObj } from 'src/pages/assets';
import { getUserEmail } from 'src/utils/UserDetails';
import { buildInlinedFontFaceCss } from 'src/utils/inlineFontFaces';
import { getCurrentEnvironment } from 'src/pages/APIs';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  mixins: [helperMixin],
  props: {
    /**
     * DOCB-13475: explicit document id so the form works on ANY screen
     * (Validation Screen, Error Screen, …) instead of relying on the
     * route shape. Falls back to `$route.params.id` when not provided.
     */
    docId: {
      type: String,
      default: '',
    },
    /** Pre-fill the editable message textarea (e.g. the error report). */
    prefillBody: {
      type: String,
      default: '',
    },
    /** Pre-fill the subject line. */
    prefillSubject: {
      type: String,
      default: '',
    },
  },
  setup() {
    return {
      loading: ref(false),
      supportDialog: ref(false),
      priorityOptions: ref([
        { label: i18n.t('very_high'), value: 'Very High' },
        { label: i18n.t('high'), value: 'High' },
        { label: i18n.t('medium'), value: 'Medium' },
        { label: i18n.t('low'), value: 'Low' },
      ]),
      supportTicket: ref({
        email: '',
        message: '',
        subject: '',
        screenshot: '',
        file: '',
        priority: { label: i18n.t('medium'), value: 'Medium' },
      } as any),
    };
  },
  mounted() {
    this.autofillmail();
    if (this.prefillBody) {
      this.supportTicket.message = this.prefillBody;
    }
    if (this.prefillSubject) {
      this.supportTicket.subject = this.prefillSubject;
    }
  },
  computed: {
    /**
     * DOCB-13475: prefer the explicit `docId` prop, fall back to the
     * route param. Guarantees the ticket body never contains the literal
     * string "DocID: undefined" when the form is mounted off a
     * document route.
     */
    resolvedDocId(): string {
      const fromProp = (this.docId || '').trim();
      if (fromProp) return fromProp;
      const fromRoute = this.$route?.params?.id;
      return typeof fromRoute === 'string' ? fromRoute : '';
    },
  },
  methods: {
    autofillmail() {
      const userdatafromlocalstorage = LocalStorage.getItem(
        'user_details',
      ) as dynamicObj | null;
      if (!userdatafromlocalstorage) return;
      // getUserEmail resolves the nested user.email the OAuth2 profile flow
      // leaves behind; a plain .username read left the field empty.
      this.supportTicket.email = getUserEmail();
      const firstName = userdatafromlocalstorage.first_name ?? '';
      const lastName = userdatafromlocalstorage.last_name ?? '';
      this.supportTicket.fullname = `${firstName} ${lastName}`.trim();
    },
    async takeScreenshot() {
      this.loading = true;
      const overlaySelectors =
        '#draw, .img-magnifier-glass, #confirmation_overlay, #score_overlay, .marquee';
      const overlays = Array.from(
        document.querySelectorAll<HTMLElement>(overlaySelectors),
      );
      const savedOpacity = overlays.map((el) => el.style.opacity);
      try {
        const { toBlob } = await import('html-to-image');
        const captureTarget = document.body;
        await document.fonts?.ready;
        const fontEmbedCSS = await buildInlinedFontFaceCss(captureTarget);
        overlays.forEach((el) => {
          el.style.opacity = '0.45';
        });
        const blob = await toBlob(captureTarget, {
          backgroundColor: document.body.classList.contains('body--dark')
            ? '#1d1d1d'
            : '#ffffff',
          skipFonts: true,
          fontEmbedCSS: fontEmbedCSS || undefined,
          imagePlaceholder:
            'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==',
        });
        if (!blob) {
          throw new Error('Screenshot capture produced no image data');
        }
        this.supportTicket.screenshot = new File([blob], 'Screenshot.png', {
          type: 'image/png',
        });
        this.showScreenshotPreview(blob);
      } catch (err) {
        logError(err);
        notify.error(this.$t('screenshot_failed'));
      } finally {
        overlays.forEach((el, index) => {
          el.style.opacity = savedOpacity[index] ?? '';
        });
        this.loading = false;
      }
    },
    showScreenshotPreview(blob: Blob) {
      const preview = document.createElement('img');
      preview.src = URL.createObjectURL(blob);
      preview.style.width = '208px';
      preview.style.height = '144px';
      document.getElementById('display')?.appendChild(preview);

      const screenButton = document.getElementById('screen-button');
      if (screenButton?.firstChild) {
        screenButton.removeChild(screenButton.firstChild);
      }
      const messageHTMLElement = document.createElement('span');
      messageHTMLElement.innerHTML = i18n.t('screenshot_taken');
      messageHTMLElement.style.color = 'green';
      screenButton?.appendChild(messageHTMLElement);
    },
    checkArrayForEmptyString() {
      return (
        this.supportTicket.email === '' ||
        this.supportTicket.message === '' ||
        this.supportTicket.fullname === '' ||
        this.supportTicket.subject === ''
      );
    },
    checkStringIfValidEmail() {
       
      return this.supportTicket.email.includes('@');
    },
    buildRequestBody() {
      const formData = new FormData();
      formData.append('fullname', this.supportTicket.fullname);
      formData.append('customer_email', this.supportTicket.email);
      const priority = this.supportTicket.priority.value;
      const channel = (window.location.pathname || '').startsWith('/nova/')
        ? 'nova'
        : 'vesta';
      const fullSubject =
        `[${getCurrentEnvironment()}][${channel}] - ` +
        this.supportTicket.subject;
      // DOCB-13475: resolve the doc id from the prop (with route fallback)
      // so the body never contains the literal "DocID: undefined" when the
      // form is mounted off a document route. Resolved INLINE (not via the
      // `resolvedDocId` computed) so unit tests that call buildRequestBody
      // with a plain `.call(context)` — where computeds don't exist — keep
      // the route fallback working.
      const resolvedDocId =
        (this.docId || '').trim() ||
        (typeof this.$route?.params?.id === 'string'
          ? this.$route.params.id
          : '');
      let body = resolvedDocId
        ? `${this.supportTicket.message}. DocID: ${resolvedDocId}`
        : this.supportTicket.message;

      // Zammad caps the ticket title at 200 chars and the backend appends
      // " (priority)" to our subject. When the title would overflow, cut it with
      // an ellipsis and continue the remainder at the top of the message body.
      const availableForSubject = 200 - ` (${priority})`.length;
      if (fullSubject.length > availableForSubject) {
        const kept = fullSubject.slice(0, availableForSubject - 3);
        const overflow = fullSubject.slice(availableForSubject - 3);
        formData.append('subject', kept + '...');
        body = '...' + overflow + '\n\n' + body;
      } else {
        formData.append('subject', fullSubject);
      }

      formData.append('priority', priority);
      formData.append('body', body);
      if (this.supportTicket.screenshot !== '') {
        formData.append('screenshot', this.supportTicket.screenshot);
      }
      if (this.supportTicket.file !== '') {
        formData.append('attachment', this.supportTicket.file);
      }
      return formData;
    },
    async sendSupportTicket() {
      try {
        this.showLoading();
        if (this.checkArrayForEmptyString()) {
          notify.error(this.$t('fill_all_fields'));
          return;
        }
        if (!this.checkStringIfValidEmail()) {
          notify.error(this.$t('invalid_email'));
          return;
        }
        await this.makeApiCall();
      } catch (err) {
        let msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        if (msg.includes('undefined')) {
          msg = ApiExceptions.translate('INVALID_SUPPORT_EMAIL');
        }
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async makeApiCall() {
      const formData = this.buildRequestBody();
      return await supportApiService
        .create_ticket(formData)
        .then((response) => {
          this.hideLoading();
          notify.success(this.$t('success'));
        })
        .catch((response) => {
          this.hideLoading();
          if (response.message.error.includes('customer')) {
            notify.error(
              this.$t('no_email_found') + ' ' + this.supportTicket.email,
            );
          } else {
            notify.error(this.$t('errors_INVALID_AUTHORIZATION_CODE'));
          }
        });
    },
  },
});
</script>

<style lang="scss" scoped>
.container-height {
  overflow-y: scroll;
}
</style>
